{
  "name": "pi-agent",
  "version": "0.1.0",
  "private": true,
  "description": "pi resources (skills, prompts) and a sandbox runner: stock pi CLI + one extension + a wrapper that writes report.json",
  "type": "module",
  "engines": {
    "node": ">=26.10.0"
  },
  "keywords": [
    "pi-package"
  ],
  "pi": {
    "extensions": [],
    "skills": [
      "./skills",
      "!skills/README.md"
    ],
    "prompts": [
      "./prompts/*.md",
      "!prompts/README.md"
    ]
  },
  "scripts": {
    "build": "node build.mjs",
    "typecheck": "tsc --noEmit",
    "test": "node --test 'src/**/*.test.ts'",
    "check": "npm run typecheck && npm test && npm run build"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "1.0.4",
    "@types/node": "^26.6.4",
    "esbuild": "^0.28.2",
    "typebox": "1.3.27",
    "typescript": "^7.0.2"
  }
}
